package dev.srpbackport.tools;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.tools.*;import com.sun.source.tree.*;import com.sun.source.util.*;
public final class EntityDataCalls {
 static final class Edit{int a,b;String text;Edit(int a,int b,String text){this.a=a;this.b=b;this.text=text;}}
 static String render(String source,int a,int b,List<Edit> edits){StringBuilder text=new StringBuilder(source.substring(a,b));List<Edit> selected=new ArrayList<Edit>();for(Edit e:edits)if(e.a>=a&&e.b<=b)selected.add(e);selected.sort((x,y)->Integer.compare(y.a,x.a));for(Edit e:selected)text.replace(e.a-a,e.b-a,e.text);return text.toString();}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]).toAbsolutePath().normalize();List<File> files=new ArrayList<File>();try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.filter(p->p.toString().endsWith(".java")&&!p.toString().replace('\\','/').contains("/backport/")).sorted().forEach(p->files.add(p.toFile()));}
  JavaCompiler compiler=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> diagnostics=new DiagnosticCollector<JavaFileObject>();StandardJavaFileManager manager=compiler.getStandardFileManager(diagnostics,null,StandardCharsets.UTF_8);JavacTask task=(JavacTask)compiler.getTask(null,manager,diagnostics,Arrays.asList("-proc:none","-source","8"),null,manager.getJavaFileObjectsFromFiles(files));Iterable<? extends CompilationUnitTree> units=task.parse();SourcePositions positions=Trees.instance(task).getSourcePositions();Map<Path,String> pending=new LinkedHashMap<Path,String>();List<String> audit=new ArrayList<String>();
  for(CompilationUnitTree unit:units){Path path=Paths.get(unit.getSourceFile().toUri());String source=new String(Files.readAllBytes(path),StandardCharsets.UTF_8);List<Edit> edits=new ArrayList<Edit>();
   new TreeScanner<Void,Void>(){
    int a(Tree t){return (int)positions.getStartPosition(unit,t);}int b(Tree t){return (int)positions.getEndPosition(unit,t);}
    void replace(Tree t,String text,String reason){int start=a(t),end=b(t);edits.removeIf(e->e.a>=start&&e.b<=end);edits.add(new Edit(start,end,text));audit.add(root.relativize(path)+"\t"+unit.getLineMap().getLineNumber(start)+"\t"+reason);}
    @Override public Void visitMemberSelect(MemberSelectTree t,Void p){super.visitMemberSelect(t,p);String name=t.getIdentifier().toString();if(name.equals("dataWatcher")||name.equals("dataManager"))replace(t,"EntityDataManager.of("+render(source,a(t.getExpression()),b(t.getExpression()),edits)+")","tracked-field");return null;}
    @Override public Void visitIdentifier(IdentifierTree t,Void p){if(t.getName().contentEquals("dataWatcher")||t.getName().contentEquals("dataManager"))replace(t,"EntityDataManager.of(this)","unqualified-tracked-field");return null;}
    @Override public Void visitMethodInvocation(MethodInvocationTree t,Void p){super.visitMethodInvocation(t,p);if(t.getArguments().isEmpty()&&t.getMethodSelect() instanceof MemberSelectTree){MemberSelectTree select=(MemberSelectTree)t.getMethodSelect();if(select.getIdentifier().contentEquals("getDataManager"))replace(t,"EntityDataManager.of("+render(source,a(select.getExpression()),b(select.getExpression()),edits)+")","tracked-getter");}return null;}
   }.scan(unit,null);
   if(edits.isEmpty())continue;boolean imported=false;for(ImportTree i:unit.getImports())if(i.getQualifiedIdentifier().toString().equals("com.dhanantry.scapeandrunparasites.backport.datasync.EntityDataManager"))imported=true;if(!imported){int at=source.indexOf(';',(int)positions.getEndPosition(unit,unit.getPackageName()))+1;edits.add(new Edit(at,at,"\n\nimport com.dhanantry.scapeandrunparasites.backport.datasync.EntityDataManager;"));}pending.put(path,render(source,0,source.length(),edits));
  }
  for(Diagnostic<?> d:diagnostics.getDiagnostics())if(d.getKind()==Diagnostic.Kind.ERROR)throw new IllegalStateException("Source parse failed: "+d);manager.close();if(args[1].equals("--apply"))for(Map.Entry<Path,String> e:pending.entrySet())Files.write(e.getKey(),e.getValue().getBytes(StandardCharsets.UTF_8));Files.write(Paths.get(args[2]),audit,StandardCharsets.UTF_8);System.out.println("Tracked-data expressions: "+audit.size()+" in "+pending.size()+" source units");
 }
}
